CREATE POLICY "Admin upload pdf-logo" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'pdf-logo' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin update pdf-logo" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'pdf-logo' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admin delete pdf-logo" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = 'pdf-logo' AND public.has_role(auth.uid(), 'admin'));